import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_M": 32, "BLOCK_N": 32, "BLOCK_K": 32, "GROUP_SIZE_M": gs},
        )
        for gs in [1, 2, 4, 8]
    ],
    key=["M", "N", "K"],
)
@triton.jit
def _matmul_kernel(
    a_ptr,
    b_ptr,
    c_ptr,
    M,
    N,
    K,
    stride_am,
    stride_ak: tl.constexpr,
    stride_bk,
    stride_bn: tl.constexpr,
    stride_cm,
    stride_cn: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    pid = tl.program_id(0)

    num_pid_m = tl.cdiv(M, BLOCK_M)
    num_pid_n = tl.cdiv(N, BLOCK_N)
    num_pid_in_group = GROUP_SIZE_M * num_pid_n

    group_id = pid // num_pid_in_group
    first_pid_m = group_id * GROUP_SIZE_M
    group_size_m = tl.minimum(num_pid_m - first_pid_m, GROUP_SIZE_M)

    pid_m = first_pid_m + ((pid % num_pid_in_group) % group_size_m)
    pid_n = (pid % num_pid_in_group) // group_size_m

    a_desc = tl.make_tensor_descriptor(
        base=a_ptr,
        shape=(M, K),
        strides=(stride_am, stride_ak),
        block_shape=(BLOCK_M, BLOCK_K),
    )
    b_desc = tl.make_tensor_descriptor(
        base=b_ptr,
        shape=(K, N),
        strides=(stride_bk, stride_bn),
        block_shape=(BLOCK_K, BLOCK_N),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    for off_k in range(0, K, BLOCK_K):
        a_tile = a_desc.load([pid_m * BLOCK_M, off_k])
        b_tile = b_desc.load([off_k, pid_n * BLOCK_N])
        acc += tl.dot(a_tile, b_tile)
    c_desc = tl.make_tensor_descriptor(
        base=c_ptr,
        shape=(M, N),
        strides=(stride_cm, stride_cn),
        block_shape=(BLOCK_M, BLOCK_N),
    )
    c_desc.store([pid_m * BLOCK_M, pid_n * BLOCK_N], acc.to(c_ptr.type.element_ty))


def _matmul_triton(A, B):
    M, K = A.shape
    K2, N = B.shape

    A = A.contiguous()
    B = B.contiguous()

    C = torch.empty((M, N), device=A.device, dtype=A.dtype)

    def grid(META):
        assert (
            M % META["BLOCK_M"] == 0
            and N % META["BLOCK_N"] == 0
            and K % META["BLOCK_K"] == 0
        ), "Matrix dimensions must be divisible by block sizes"
        return (triton.cdiv(M, META["BLOCK_M"]) * triton.cdiv(N, META["BLOCK_N"]),)

    _matmul_kernel[grid](
        A,
        B,
        C,
        M,
        N,
        K,
        A.stride(0),
        A.stride(1),
        B.stride(0),
        B.stride(1),
        C.stride(0),
        C.stride(1),
        assume_in_bounds=True,
    )
    return C


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matmul_triton(A, B)


M = 256
N = 256
K = 131072 * 4


def get_inputs():
    A = torch.rand(M, K, dtype=torch.bfloat16)
    B = torch.rand(K, N, dtype=torch.bfloat16)
    return [A, B]


def get_init_inputs():
    return []
